import DefaultValue from "../Core/DefaultValue.js"
import Cartesian3 from "../Core/Cartesian3.js";
import Layer3DProvider from "./Layer3DProvider";
/**
 * @vuepress
 *
 * ---
 * title: PIE-Map UE
 * headline: 场景模块
 * ---
 */

/**
 * osgb参数
 * @name OSGBProvider
 * @extends Layer3DProvider
 *
 */
class OSGBProvider extends Layer3DProvider {
    constructor(options) {
        super(options);

        this.uri = DefaultValue(options.uri, "");

        this.url = DefaultValue(options.url, "");

        this.tileUrl = DefaultValue(options.tileUrl, "");

        this.cacheUrl = DefaultValue(options.cacheUrl, "");

        this.position = DefaultValue(options.position, new Cartesian3());

        this.offset = DefaultValue(options.offset, new Cartesian3());

        this.autoProjection = DefaultValue(options.autoProjection, true);

        this.providerName = "OSGBProvider";
    }
}

export default OSGBProvider;