import DefaultValue from "../Core/DefaultValue.js";
import GenerateGuid from "../Core/GenerateGuid.js";
import Defined from "../Core/Defined.js";
import CreateRawPropertyDescriptor from "./CreateRawPropertyDescriptor.js"

import BillboardGraphics from "./BillboardGraphics.js";
import BoxGraphics from "./BoxGraphics.js";
import ModelGraphics from "./ModelGraphics.js";
import PointGraphics from "./PointGraphics.js";
import PolygonGraphics from "./PolygonGraphics.js";
import PolylineGraphics from "./PolylineGraphics.js";
/**
 * @vuepress
 *
 * ---
 * title: PIE-Map UE
 * headline: 数据源模块
 * ---
 */

/**
 * 实体操作函数
 * @name Entity
 * @class Entity
 * 实体
 */
class Entity {
    constructor(options){
        options = DefaultValue(options, DefaultValue.EMPTY_OBJECT);
        this.id = DefaultValue(options.id,GenerateGuid());
        this.name = DefaultValue(options.name,"defaultEntity");

        this._propertyNames = [
            "billboard",
            "box",
            "model",
            "point",
            "polygon",
            "polyline",
        ];

        this.box = undefined;
        this.model = undefined;
        this.point = undefined;
        this.polygon = undefined;
        this.polyline = undefined;

        var billboardOptions = DefaultValue(options.billboard,undefined);
        if(billboardOptions){
            this.billboard = new BillboardGraphics(billboardOptions);
        }

        var modelOptions = DefaultValue(options.model,undefined);
        if(modelOptions){
            this.model = new ModelGraphics(modelOptions);
        }
    }
}

export default Entity;