/**
 * 影像数据参数基类
 * @name ImageryProvider
 * @class ImageryProvider
 * 影像数据参数
 */
class ImageryProvider {
    constructor(options){
        this.label = DefaultValue(options.label, "defaultLabel");

        this.guid = DefaultValue(options.guid, GenerateGuid());

        this.providerName = undefined;
    }
}

export default ImageryProvider;