import  Config  from "./Config.js";

/**
 *
 * 类对象基类
 * @name Object
 * @class Object
 * 基类操作函数
 */
let BaseObject = function() {
    this.name = "BaseObject";
    this.pre = null;
}

Object.assign(BaseObject.prototype, {

    _evaluate: function () {
        var evaluate = { function: "evaluate", statement: this.statement };
        let statement = Config.formatURLParam(evaluate);
        return statement;
    },

    /**
     * 获取信息
     *
     * @memberOf Object#
     * @returns {String} 返回信息
     */
    getInfo: function() {
        return this.statement;
    },

    /**
     * json对象转string对象
     *
     * @memberOf Object#
     * @returns {String}  返回string对象
     */
    toString: function() {
        return JSON.stringify(this.statement).toString();
    },

} );

export default BaseObject;
