const lerpScratch = new Cartesian3();
/**
 * 使用提供的笛卡尔坐标计算t点的线性插值
 *
 * @param {Cartesian3} start  -t在0.0处的值
 * @param {Cartesian3} end  -t在1.0处对应的值
 * @param {Number} t  -沿着t进行插值的点
 * @param {Cartesian3} result  -将结果存储在其上的对象
 *
 * @memberOf Cartesian3
 * @returns {Cartesian3} 返回t点的线性插值
 */
Cartesian3.lerp = function (start, end, t, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.object("start", start);
  Check.typeOf.object("end", end);
  Check.typeOf.number("t", t);
  Check.typeOf.object("result", result);
  //>>includeEnd('debug');

  Cartesian3.multiplyByScalar(end, t, lerpScratch);
  result = Cartesian3.multiplyByScalar(start, 1.0 - t, result);
  return Cartesian3.add(lerpScratch, result, result);
};

const angleBetweenScratch = new Cartesian3();
const angleBetweenScratch2 = new Cartesian3();
/**
 * 计算笛卡尔坐标之间的角度(以弧度为单位）
 *
 * @param {Cartesian3} left  -第一个笛卡尔坐标
 * @param {Cartesian3} right  -第二个笛卡尔坐标
 *
 * @memberOf Cartesian3
 * @returns {Number}  返回两个坐标之间的角度
 */
Cartesian3.angleBetween = function (left, right) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.object("left", left);
  Check.typeOf.object("right", right);
  //>>includeEnd('debug');

  Cartesian3.normalize(left, angleBetweenScratch);
  Cartesian3.normalize(right, angleBetweenScratch2);
  const cosine = Cartesian3.dot(angleBetweenScratch, angleBetweenScratch2);
  const sine = Cartesian3.magnitude(
    Cartesian3.cross(
      angleBetweenScratch,
      angleBetweenScratch2,
      angleBetweenScratch
    )
  );
  return Math.atan2(sine, cosine);
};

const mostOrthogonalAxisScratch = new Cartesian3();
/**
 * 返回与所提供的直角坐标最正交的轴
 *
 * @param {Cartesian3} cartesian  -在笛卡尔坐标系上找到最正交的轴
 * @param {Cartesian3} result  -将结果存储于其上的对象
 *
 * @memberOf Cartesian3
 * @returns {Cartesian3}   返回最正交的轴
 */
Cartesian3.mostOrthogonalAxis = function (cartesian, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.object("cartesian", cartesian);
  Check.typeOf.object("result", result);
  //>>includeEnd('debug');

  const f = Cartesian3.normalize(cartesian, mostOrthogonalAxisScratch);
  Cartesian3.abs(f, f);

  if (f.x <= f.y) {
    if (f.x <= f.z) {
      result = Cartesian3.clone(Cartesian3.UNIT_X, result);
    } else {
      result = Cartesian3.clone(Cartesian3.UNIT_Z, result);
    }
  } else if (f.y <= f.z) {
    result = Cartesian3.clone(Cartesian3.UNIT_Y, result);
  } else {
    result = Cartesian3.clone(Cartesian3.UNIT_Z, result);
  }

  return result;
};

/**
 * 把向量a投射到向量b上
 *
 * @param {Cartesian3} a  -需要投射的向量
 * @param {Cartesian3} b  -投影到的向量
 * @param {Cartesian3} result  -笛卡尔形式的结果
 *
 * @memberOf Cartesian3
 * @returns {Cartesian3}  返回最终的笛卡尔坐标
 */
Cartesian3.projectVector = function (a, b, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.defined("a", a);
  Check.defined("b", b);
  Check.defined("result", result);
  //>>includeEnd('debug');

  const scalar = Cartesian3.dot(a, b) / Cartesian3.dot(b, b);
  return Cartesian3.multiplyByScalar(b, scalar, result);
};

/**
 * 比较两个笛卡尔坐标是否相等
 *
 * @param {Cartesian3} left  -第一个笛卡尔坐标
 * @param {Cartesian3} right  -第二个笛卡尔坐标
 *
 * @memberOf Cartesian3
 * @returns {Boolean}  如果相等返回true，否则返回false
 */
Cartesian3.equals = function (left, right) {
  return (
    left === right ||
    (defined(left) &&
      defined(right) &&
      left.x === right.x &&
      left.y === right.y &&
      left.z === right.z)
  );
};

/**
 *
 * @param {} cartesian -
 * @param {} array -
 * @param {} offset -
 *
 * @memberOf Cartesian3
 * @returns {Boolean}
 */
Cartesian3.equalsArray = function (cartesian, array, offset) {
  return (
    cartesian.x === array[offset] &&
    cartesian.y === array[offset + 1] &&
    cartesian.z === array[offset + 2]
  );
};

/**
 * 按分量比较所提供的笛卡尔坐标
 *
 * @param {Cartesian3} left  -第一个笛卡尔坐标
 * @param {Cartesian3} right  -第二个笛卡尔坐标
 * @param {Number} relativeEpsilon  -用于相等性检验的相对容差
 * @param {Number} absoluteEpsilon  -用于相等性检验的绝对容差
 *
 * @memberOf Cartesian3
 * @returns {Boolean} 如果两个坐标位于Epsilon之内，则返回true，否则返回false
 */
Cartesian3.equalsEpsilon = function (
  left,
  right,
  relativeEpsilon,
  absoluteEpsilon
) {
  return (
    left === right ||
    (defined(left) &&
      defined(right) &&
      CesiumMath.equalsEpsilon(
        left.x,
        right.x,
        relativeEpsilon,
        absoluteEpsilon
      ) &&
      CesiumMath.equalsEpsilon(
        left.y,
        right.y,
        relativeEpsilon,
        absoluteEpsilon
      ) &&
      CesiumMath.equalsEpsilon(
        left.z,
        right.z,
        relativeEpsilon,
        absoluteEpsilon
      ))
  );
};

/**
 * 计算两个笛卡尔坐标的外积
 *
 * @param {Cartesian3} left  -第一个笛卡尔坐标
 * @param {Cartesian3} right  -第二个笛卡尔坐标
 * @param {Cartesian3} result  -将结果存储于其上的对象
 *
 * @memberOf Cartesian3
 * @returns {Cartesian3} 返回两个笛卡尔坐标的外积
 */
Cartesian3.cross = function (left, right, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.object("left", left);
  Check.typeOf.object("right", right);
  Check.typeOf.object("result", result);
  //>>includeEnd('debug');

  const leftX = left.x;
  const leftY = left.y;
  const leftZ = left.z;
  const rightX = right.x;
  const rightY = right.y;
  const rightZ = right.z;

  const x = leftY * rightZ - leftZ * rightY;
  const y = leftZ * rightX - leftX * rightZ;
  const z = leftX * rightY - leftY * rightX;

  result.x = x;
  result.y = y;
  result.z = z;
  return result;
};

/**
 * 计算两个笛卡尔坐标之间的中点
 *
 * @param {Cartesian3} left  -第一个笛卡尔坐标
 * @param {Cartesian3} right  -第二个笛卡尔坐标
 * @param {Cartesian3} result  -将结果存储于其上的对象
 *
 * @memberOf Cartesian3
 * @returns {Cartesian3}  返回中点坐标
 */
Cartesian3.midpoint = function (left, right, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.object("left", left);
  Check.typeOf.object("right", right);
  Check.typeOf.object("result", result);
  //>>includeEnd('debug');

  result.x = (left.x + right.x) * 0.5;
  result.y = (left.y + right.y) * 0.5;
  result.z = (left.z + right.z) * 0.5;

  return result;
};

/**
 * 用以度为单位的经度和纬度值计算笛卡尔坐标
 *
 * @param {Number} longitude  -以度为单位的经度
 * @param {Number} latitude   -以度为单位的纬度
 * @param {Number} height  -椭球以上的高度，单位为米
 * @param {Ellipsoid} ellipsoid  -椭球所在位置
 * @param {Cartesian3} [result]  -将结果存储于其上的对象
 *
 * @memberOf Cartesian3
 * @returns {Cartesian3}  返回计算出的笛卡尔坐标
 * @example
 * const position = Cesium.Cartesian3.fromDegrees(-115.0, 37.0);
 */
Cartesian3.fromDegrees = function (
  longitude,
  latitude,
  height,
  ellipsoid,
  result
) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.number("longitude", longitude);
  Check.typeOf.number("latitude", latitude);
  //>>includeEnd('debug');

  longitude = CesiumMath.toRadians(longitude);
  latitude = CesiumMath.toRadians(latitude);
  return Cartesian3.fromRadians(longitude, latitude, height, ellipsoid, result);
};

let scratchN = new Cartesian3();
let scratchK = new Cartesian3();
const wgs84RadiiSquared = new Cartesian3(
  6378137.0 * 6378137.0,
  6378137.0 * 6378137.0,
  6356752.3142451793 * 6356752.3142451793
);

/**
 * 用以弧度表示的经度和纬度值计算笛卡尔坐标
 *
 * @param {Number} longitude  -以弧度为单位的经度
 * @param {Number} latitude  -以弧度为单位的纬度
 * @param {Number} height  -椭球以上的高度，单位为米
 * @param {Ellipsoid} ellipsoid  -椭球所在位置
 * @param {Cartesian3} [result]  -将结果存储于其上的对象
 *
 * @memberOf Cartesian3
 * @returns {Cartesian3}  返回计算出的笛卡尔坐标
 * @example
 * const position = Cesium.Cartesian3.fromRadians(-2.007, 0.645);
 */
Cartesian3.fromRadians = function (
  longitude,
  latitude,
  height,
  ellipsoid,
  result
) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.number("longitude", longitude);
  Check.typeOf.number("latitude", latitude);
  //>>includeEnd('debug');

  height = defaultValue(height, 0.0);
  const radiiSquared = Defined(ellipsoid)
    ? ellipsoid.radiiSquared
    : wgs84RadiiSquared;

  const cosLatitude = Math.cos(latitude);
  scratchN.x = cosLatitude * Math.cos(longitude);
  scratchN.y = cosLatitude * Math.sin(longitude);
  scratchN.z = Math.sin(latitude);
  scratchN = Cartesian3.normalize(scratchN, scratchN);

  Cartesian3.multiplyComponents(radiiSquared, scratchN, scratchK);
  const gamma = Math.sqrt(Cartesian3.dot(scratchN, scratchK));
  scratchK = Cartesian3.divideByScalar(scratchK, gamma, scratchK);
  scratchN = Cartesian3.multiplyByScalar(scratchN, height, scratchN);

  if (!Defined(result)) {
    result = new Cartesian3();
  }
  return Cartesian3.add(scratchK, scratchN, result);
};

/**
 * 计算用度表示的经度和纬度值数组的笛卡尔坐标数组
 *
 * @param {Array} coordinates  -经度和纬度值的列表
 * @param {Ellipsoid} ellipsoid  -坐标所在的椭球
 * @param {Array} result  -用于存储结果的Cartesian3对象数组
 *
 * @memberOf Cartesian3
 * @returns {Array} 笛卡尔坐标数组
 * @example
 * const positions = Cesium.Cartesian3.fromDegreesArray([-115.0, 37.0, -107.0, 33.0]);
 */
Cartesian3.fromDegreesArray = function (coordinates, ellipsoid, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.defined("coordinates", coordinates);
  if (coordinates.length < 2 || coordinates.length % 2 !== 0) {
    throw new DeveloperError(
      "the number of coordinates must be a multiple of 2 and at least 2"
    );
  }
  //>>includeEnd('debug');

  const length = coordinates.length;
  if (!Defined(result)) {
    result = new Array(length / 2);
  } else {
    result.length = length / 2;
  }

  for (let i = 0; i < length; i += 2) {
    const longitude = coordinates[i];
    const latitude = coordinates[i + 1];
    const index = i / 2;
    result[index] = Cartesian3.fromDegrees(
      longitude,
      latitude,
      0,
      ellipsoid,
      result[index]
    );
  }

  return result;
};

