import Defined from "../engine/source/Core/Defined.js";
import DeveloperError from "../engine/source/Core/DeveloperError.js";
import GetElement from "../engine/source/DataSources/getElement.js";
import Scene from "../engine/source/Scene/Scene.js";
import DefaultValue from "../engine/source/Core/DefaultValue.js";
import Execute from "../engine/source/Core/Execute.js";

function Viewer(container, options) {
//>>includeStart('debug', pragmas.debug);
//     if (!Defined(container)) {
//         throw new DeveloperError("container is required.");
//     }
//     //>>includeEnd('debug');
//     container = GetElement(container);
//     options = defaultValue(options, defaultValue.EMPTY_OBJECT);


    //连接webSocket
    var wsUrl = DefaultValue(options.wsUrl, new Scene(""));
    if(!Defined(wsUrl)){
        throw new DeveloperError("wsUrl is NULL.");
    }
    var execute = new Execute();
    execute.load(wsUrl, function () {});

    //scene
    var scene = DefaultValue(options.scene, new Scene("defaultScene"));


    //terrainProvider
    var terrainProvider = DefaultValue(options.terrainProvider, undefined);


    this._execute = execute;
    this._container = container;
    this._scene = scene;
    this.terrainProvider = terrainProvider;
}
Object.defineProperties(Viewer.prototype, {
    /**
     * Gets the parent container.
     * @memberof Viewer.prototype
     * @type {Element}
     * @readonly
     */
    container: {
        get: function () {
            return this._container;
        },
    },

    /**
     * Gets the scene.
     * @memberof Viewer.prototype
     * @type {Element}
     * @readonly
     */
    scene: {
        get: function () {
            return this._scene;
        },
    },

    /**
     * Gets the camera.
     * @memberof Viewer.prototype
     * @type {Element}
     * @readonly
     */
    camera: {
        get: function () {
            return this._scene.getCamera();
        },
    },

    /**
     * Set/Gets the terrainProvider.
     * @memberof Viewer.prototype
     * @type {Element}
     * @readonly
     */
    terrainProvider: {
        get: function () {
            return this._terrainProvider;
        },
        set: function (value) {
            if(value){
                var result =  new Promise((resolve) => {
                    var setTerrainProvider = this.scene.setTerrainProvider(value);
                    this.execute(setTerrainProvider, function (data) {
                        resolve(data);
                    });
                });
                this._terrainProvider = value;
            }
        }
    },

    /**
     * Gets the imageryLayers.
     * @memberof Viewer.prototype
     * @type {Element}
     * @readonly
     */
    imageryLayers: {
        get: function () {
            return this._scene.getImageryLayers();
        },
    },

    /**
     * Gets the layers3D.
     * @memberof Viewer.prototype
     * @type {Element}
     * @readonly
     */
    layers3D: {
        get: function () {
            return this._scene.get3DLayers();
        },
    },

    /**
     * Gets the entities.
     * @memberof Viewer.prototype
     * @type {Element}
     * @readonly
     */
    entities: {
        get: function () {
            return this._scene.getEntities();
        },
    },
})


Viewer.prototype.flyTo = function (options) {
    return new Promise((resolve) => {
        var result = this.camera.flyTo(options.long, options.lat, options.zoomDistance, options.pitch, options.heading);
        this.execute(result, function (data) {
            resolve(data);
        });
    });
};

Viewer.prototype.execute = function (element,callBack) {
    return this._execute.run(element,callBack);
};

Viewer.prototype.addListener = function (listener) {
    return this._execute.addListener(listener);
};

Viewer.prototype.removeListener = function (listener) {
    return this._execute.removeListener(listener);
};


export default Viewer;