import  BaseObject from "../Core/BaseObject.js";
/**
 * @vuepress
 *
 * ---
 * title: PIE-Map UE
 * headline: 场景模块
 * ---
 */

/**
 *
 * 相机操作函数
 * @name Camera
 *
 * @extends BaseObject
 */
class Camera extends BaseObject {
    constructor(name) {
        super("Camera");
        this.name = name;

        this.pre = null;
        this.statement = {
            type: "Invocation",
            arguments: {
                name: name,
            },
            functionName: "Camera"
        };
    }
}

Object.assign(Camera.prototype,{
    /**
     * 飞行动画
     * @param {Number} long -经度
     * @param {Number} lat -纬度
     * @param {Number} zoomDistance -缩放距离
     * @param {Number} pitch -俯仰角
     * @param {Number} heading -偏航角
     *
     * @memberOf Camera#
     * @returns {Camera} 返回相机
     */
    flyTo(long, lat, zoomDistance, pitch, heading) {
        var camera = this.statement;
        var obj = {
            type: "Invocation",
            arguments: {
                camera:camera,
                long:long,
                lat:lat,
                zoomDistance:zoomDistance,
                pitch:pitch,
                heading:heading
            },
            functionName: "Camera.flyTo"
        };

        var cameraObject = new Camera();
        cameraObject.pre = this;
        cameraObject.statement = obj;
        return cameraObject;
    },

    /**
     * 使用目标和偏移量设置摄像机的位置和方向
     * @param {Number} long -经度
     * @param {Number} lat -纬度
     * @param {Number} zoomDistance -缩放距离
     * @param {Number} pitch -俯仰角
     * @param {Number} heading -偏航角
     *
     * @memberOf Camera#
     * @returns {Camera}  返回相机
     */
    lookAt (long, lat, zoomDistance, pitch, heading){
        var camera = this.statement;
        var obj = {
            type: "Invocation",
            arguments: {
                camera:camera,
                long:long,
                lat:lat,
                zoomDistance:zoomDistance,
                pitch:pitch,
                heading:heading
            },
            functionName: "Camera.lookAt"
        };

        var cameraObject = new Camera();
        cameraObject.pre = this;
        cameraObject.statement = obj;
        return cameraObject;
    },

    /**
     * 执行命令(临时接口)
     * @param {params} params -命令参数(json格式)
     *
     * @memberOf Camera#
     * @returns {Camera}  返回相机
     */
    doCommand(params){
        var camera = this.statement;
        var obj = {
            type: "Invocation",
            arguments: {
                camera:camera,
                params:params,
            },
            functionName: "Camera.doCommand"
        };
        var cameraObject = new Camera();
        cameraObject.pre = this;
        cameraObject.statement = obj;
        return cameraObject;
    },

    /**
     * 地理坐标转世界坐标
     * @param {params} params -坐标参数
     *
     * @memberOf Camera#
     * @returns {Camera}  返回相机
     */
    geoToWorld(geoX,geoY,worldX,worldY,worldZ){
        var camera = this.statement;
        var obj = {
            type: "Invocation",
            arguments: {
                camera:camera,
                geoX:geoX,
                geoY:geoY,
                worldX:worldX,
                worldY:worldY,
                worldZ:worldZ
            },
            functionName: "Camera.geoToWorld"
        };
        var cameraObject = new Camera();
        cameraObject.pre = this;
        cameraObject.statement = obj;
        return cameraObject;
    },

    /**
     * 世界坐标转屏幕
     * @param {params} params -坐标参数
     *
     * @memberOf Camera#
     * @returns {Camera}  返回相机
     */
    worldToScreen(worldX,worldY,worldZ,ScreenX,ScreenY){
        var camera = this.statement;
        var obj = {
            type: "Invocation",
            arguments: {
                camera:camera,
                worldX:worldX,
                worldY:worldY,
                worldZ:worldZ,
                ScreenX:ScreenX,
                ScreenY:ScreenY
            },
            functionName: "Camera.worldToScreen"
        };
        var cameraObject = new Camera();
        cameraObject.pre = this;
        cameraObject.statement = obj;
        return cameraObject;
    },

    getInfo(){
        var camera = this.statement;
        var obj = {
            type: "Invocation",
            arguments: {
                camera:camera
            },
            functionName: "Camera.getInfo"
        };
        var cameraObject = new Camera();
        cameraObject.pre = this;
        cameraObject.statement = obj;
        return cameraObject;
    }

})

export default Camera;
