import DefaultValue from "../Core/DefaultValue.js"
import TerrainProvider from "./TerrainProvider.js";
/**
 * @vuepress
 *
 * ---
 * title: PIE-Map UE
 * headline: 场景模块
 * ---
 */

/**
 * cesium地形参数操作函数
 * @name EngineTerrainProvider
 * @extends TerrainProvider
 *
 */
class EngineTerrainProvider extends TerrainProvider {
    constructor(options) {
        super(options);

        this.url = DefaultValue(options.url, "");

        this.cacheUrl = DefaultValue(options.cacheUrl, "");

        this.minLevel = DefaultValue(options.minLevel, 0);

        this.maxLevel = DefaultValue(options.maxLevel, 18);

        this.isTMSServer = DefaultValue(options.isTMSServer, true);

        this.providerName = "EngineTerrainProvider";
    }

}

export default EngineTerrainProvider;