import Cartesian3 from "./Cartesian3.js";
import Check from "./Check.js";
import EngineMath from "./Math.js";
import DefaultValue from "./DefaultValue.js";
import Defined from "./Defined.js";
import ScaleToGeodeticSurface from "./ScaleToGeodeticSurface.js";

/**
 * 通过经度，纬度和高度确定的点
 * @name Cartographic
 * @class Cartographic
 *
 * @param {Number} longitude  -经度
 * @param {Number} latitude  -纬度
 * @param {Number} height  -高度
 *
 */
function Cartographic(longitude, latitude, height) {
  this.longitude = DefaultValue(longitude, 0.0);
  this.latitude = DefaultValue(latitude, 0.0);
  this.height = DefaultValue(height, 0.0);
}

/**
 * 用以弧度表示的经度和纬度创建一个新的实例
 *
 * @param {Number} longitude  -以弧度表示的经度
 * @param {Number} latitude  -以弧度表示的纬度
 * @param {Number} height -椭球以上的高度，单位为米
 * @param {Cartographic} result  -将结果存储于其上的对象
 *
 *
 * @memberOf Cartographic
 * @returns {Cartographic}  返回修改后的结果参数或一个新的制图实例(如果没有提供的话)
 */
Cartographic.fromRadians = function (longitude, latitude, height, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.number("longitude", longitude);
  Check.typeOf.number("latitude", latitude);
  //>>includeEnd('debug');

  height = DefaultValue(height, 0.0);

  if (!Defined(result)) {
    return new Cartographic(longitude, latitude, height);
  }

  result.longitude = longitude;
  result.latitude = latitude;
  result.height = height;
  return result;
};

/**
 * 从经度和纬度创建一个新的制图实例
 *
 * @param {Number} longitude  -以度为单位的经度
 * @param {Number} latitude  -以度为单位的纬度
 * @param {Number} height   -椭球上方的高度，以米为单位
 * @param {Cartographic} result  -结果存储到的对象
 *
 * @memberOf Cartographic
 * @returns {Cartographic}  返回修改后的结果参数或一个新的制图实例（如果未提供）
 */
Cartographic.fromDegrees = function (longitude, latitude, height, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.typeOf.number("longitude", longitude);
  Check.typeOf.number("latitude", latitude);
  //>>includeEnd('debug');
  longitude = EngineMath.toRadians(longitude);
  latitude = EngineMath.toRadians(latitude);

  return Cartographic.fromRadians(longitude, latitude, height, result);
};

const cartesianToCartographicN = new Cartesian3();
const cartesianToCartographicP = new Cartesian3();
const cartesianToCartographicH = new Cartesian3();
const wgs84OneOverRadii = new Cartesian3(
  1.0 / 6378137.0,
  1.0 / 6378137.0,
  1.0 / 6356752.3142451793
);
const wgs84OneOverRadiiSquared = new Cartesian3(
  1.0 / (6378137.0 * 6378137.0),
  1.0 / (6378137.0 * 6378137.0),
  1.0 / (6356752.3142451793 * 6356752.3142451793)
);
const wgs84CenterToleranceSquared = EngineMath.EPSILON1;

/**
 * 从笛卡尔位置创建一个新的制图实例
 *
 * @param {Cartesian3} cartesian  -要转换为制图表达的笛卡尔位置
 * @param {Ellipsoid} ellipsoid  -位置所在的椭圆体
 * @param {Cartographic} result  -将结果存储到的对象
 *
 * @memberOf Cartographic
 * @returns {Cartographic}  返回修改后的结果参数，如果未提供，则为新的制图实例；如果笛卡尔位于椭圆体的中心，则为未定义
 */
Cartographic.fromCartesian = function (cartesian, ellipsoid, result) {
  const oneOverRadii = Defined(ellipsoid)
    ? ellipsoid.oneOverRadii
    : wgs84OneOverRadii;
  const oneOverRadiiSquared = Defined(ellipsoid)
    ? ellipsoid.oneOverRadiiSquared
    : wgs84OneOverRadiiSquared;
  const centerToleranceSquared = Defined(ellipsoid)
    ? ellipsoid._centerToleranceSquared
    : wgs84CenterToleranceSquared;

  //`cartesian is required.` is thrown from scaleToGeodeticSurface
  const p = scaleToGeodeticSurface(
    cartesian,
    oneOverRadii,
    oneOverRadiiSquared,
    centerToleranceSquared,
    cartesianToCartographicP
  );

  if (!Defined(p)) {
    return undefined;
  }

  let n = Cartesian3.multiplyComponents(
    p,
    oneOverRadiiSquared,
    cartesianToCartographicN
  );
  n = Cartesian3.normalize(n, n);

  const h = Cartesian3.subtract(cartesian, p, cartesianToCartographicH);

  const longitude = Math.atan2(n.y, n.x);
  const latitude = Math.asin(n.z);
  const height =
    EngineMath.sign(Cartesian3.dot(h, cartesian)) * Cartesian3.magnitude(h);

  if (!Defined(result)) {
    return new Cartographic(longitude, latitude, height);
  }
  result.longitude = longitude;
  result.latitude = latitude;
  result.height = height;
  return result;
};

/**
 * 根据制图输入创建一个新的Cartesian3实例
 *
 * @param {Cartographic} cartographic  -输入将转换为Cartesian3输出
 * @param {Ellipsoid} ellipsoid  -位置所在的椭圆体
 * @param {Cartesian3} result  -将结果存储到的对象
 *
 * @memberOf Cartographic
 * @returns {Cartesian3}  返回创建的实例
 */
Cartographic.toCartesian = function (cartographic, ellipsoid, result) {
  //>>includeStart('debug', pragmas.debug);
  Check.defined("cartographic", cartographic);
  //>>includeEnd('debug');

  return Cartesian3.fromRadians(
    cartographic.longitude,
    cartographic.latitude,
    cartographic.height,
    ellipsoid,
    result
  );
};

/**
 * 复制实例
 *
 * @param {Cartographic} cartographic  -要复制的实例
 * @param {Cartographic} result  -将结果存储的对象
 *
 * @memberOf Cartographic
 * @returns {Cartographic}  返回修改后的结果参数或一个新的制图实例（如果未提供）
 */
Cartographic.clone = function (cartographic, result) {
  if (!Defined(cartographic)) {
    return undefined;
  }
  if (!Defined(result)) {
    return new Cartographic(
      cartographic.longitude,
      cartographic.latitude,
      cartographic.height
    );
  }
  result.longitude = cartographic.longitude;
  result.latitude = cartographic.latitude;
  result.height = cartographic.height;
  return result;
};

/**
 * 将提供的内容与此制图成分进行比较
 *
 * @param {Cartographic} left  -第一个实例
 * @param {Cartographic} right  -第二个实例
 *
 * @memberOf Cartographic
 * @returns {Boolean}  如果两个实例相等返回true，否则返回false
 */
Cartographic.equals = function (left, right) {
  return (
    left === right ||
    (Defined(left) &&
      Defined(right) &&
      left.longitude === right.longitude &&
      left.latitude === right.latitude &&
      left.height === right.height)
  );
};

/**
 * 将提供的内容与此制图成分进行比较
 *
 * @param {Cartographic} left  -第一个实例
 * @param {Cartographic} right  -第二个实例
 * @param {Number} epsilon  -用于相等性测试的epsilon
 *
 * @memberOf Cartographic
 * @returns {Boolean}  如果两个实例在提供的epsilon之内，返回true，否则返回false
 */
Cartographic.equalsEpsilon = function (left, right, epsilon) {
  epsilon = DefaultValue(epsilon, 0);

  return (
    left === right ||
    (Defined(left) &&
      Defined(right) &&
      Math.abs(left.longitude - right.longitude) <= epsilon &&
      Math.abs(left.latitude - right.latitude) <= epsilon &&
      Math.abs(left.height - right.height) <= epsilon)
  );
};

/**
 * 初始化为(0.0,0.0,0.0)的不可变制图实例
 *
 * @memberOf Cartographic
 */
Cartographic.ZERO = Object.freeze(new Cartographic(0.0, 0.0, 0.0));

/**
 * 复制此实例
 *
 * @param {Cartographic} result  -存储结果的对象
 *
 * @memberOf Cartographic
 * @returns {Cartographic}  返回修改后的结果参数或一个新的制图实例（如果未提供）
 */
Cartographic.prototype.clone = function (result) {
  return Cartographic.clone(this, result);
};


/**
 * 将提供的内容与此制图成分进行比较
 *
 * @param {Cartographic} right  -用来比较的实例
 *
 * @memberOf Cartographic
 * @returns {Boolean}  如果两个实例相等返回true，否则返回false
 */
Cartographic.prototype.equals = function (right) {
  return Cartographic.equals(this, right);
};


/**
 * 将提供的内容与此制图成分进行比较
 *
 * @param {Cartographic} right  -用来比较的实例
 * @param {Number} epsilon  -用于相等性测试的epsilon
 *
 * @memberOf Cartographic
 * @returns {Boolean}  如果两个实例在提供的epsilon之内，返回true，否则返回false
 */
Cartographic.prototype.equalsEpsilon = function (right, epsilon) {
  return Cartographic.equalsEpsilon(this, right, epsilon);
};

/**
 * 创建以'(经度，纬度，高度)'格式表示此地图的字符串
 *
 * @memberOf Cartographic
 * @returns {String} 返回以'(经度，纬度，高度)'格式表示此地图的字符串
 */
Cartographic.prototype.toString = function () {
  return `(${this.longitude}, ${this.latitude}, ${this.height})`;
};
export default Cartographic;
