let Config = {
    API: {wsUrl: "ws://localhost:8081",},

    formatURLParam: function(value) {
        let _value = JSON.stringify(value);
        _value = encodeURIComponent(_value);
        _value = _value.replace("%20", " ")
        return _value
    },
    formatDate: function(date, fmt) {
        let o = {
            "M+" : date.getMonth()+1,                 //月份
            "d+" : date.getDate(),                    //日
            "h+" : date.getHours(),                   //小时
            "m+" : date.getMinutes(),                 //分
            "s+" : date.getSeconds(),                 //秒
            "q+" : Math.floor((date.getMonth()+3)/3), //季度
            "S"  : date.getMilliseconds()             //毫秒
        };
        if(/(y+)/.test(fmt))
            fmt=fmt.replace(RegExp.$1, (date.getFullYear()+"").substr(4 - RegExp.$1.length));
        for(let k in o)
            if(new RegExp("("+ k +")").test(fmt))
                fmt = fmt.replace(RegExp.$1, (RegExp.$1.length===1) ? (o[k]) : (("00"+ o[k]).substr((""+ o[k]).length)));
        return fmt;
    },
    checkIsString(data) {
        return typeof data === "string" && data.constructor === String;
    },
    checkIsNumber(data) {
        return typeof data === "number" && data.constructor === Number;
    },
    checkIsArray(data) {
        return typeof data === "object" && data.constructor === Array;
    },
    checkIsObject(data) {
        return typeof data === "object" && data.constructor === Object;
    },
    checkIsDate(data) {
        return typeof data === "object" && data.constructor === Date;
    },
    checkIsBoolean(data) {
        return typeof data === "boolean" && data.constructor === Boolean;
    },
    checkIsFunction(data) {
        return typeof data === "function";
    }
};

export default Config;
