import BoundingRectangle from "../Core/BoundingRectangle.js";
import DefaultValue from "../Core/DefaultValue.js"
import ImageryProvider from "./ImageryProvider.js";
/**
 * @vuepress
 *
 * ---
 * title: PIE-Map UE
 * headline: 场景模块
 * ---
 */

/**
 * 模板类影像参数
 * @name UrlTemplateImageryProvider
 *
 * @extends ImageryProvider
 */
class UrlTemplateImageryProvider extends ImageryProvider {
    constructor(options) {
        super(options);

        this.uri = DefaultValue(options.uri, "");

        this.url = DefaultValue(options.url, "");

        this.cacheUrl = DefaultValue(options.cacheUrl, "");

        this.boundingRectangle = DefaultValue(options.boundingRectangle, BoundingRectangle.MAX_VALUE);

        this.epsg = DefaultValue(options.epsg, 3857);

        this.providerName = "UrlTemplateImageryProvider";
    }
}

export default UrlTemplateImageryProvider;